REPORT_CSS = """
.rep-title{font-size:1.05rem;font-weight:700;color:#b9ffd9;text-shadow:0 0 12px rgba(0,230,118,.35)}
.st-key-dl_md,.st-key-dl_md [data-testid="stDownloadButton"]{width:100% !important}
.st-key-dl_md button{min-height:0 !important;padding:.3rem .9rem !important;font-size:.8rem !important;width:100% !important}

.st-key-report{padding:.2rem .6rem}
.st-key-report [data-testid="stHeaderActionElements"]{display:none !important}
.st-key-report p,.st-key-report li{font-size:.9rem !important;line-height:1.7 !important;color:#d4f5e2}
.st-key-report h1{font-size:1.3rem !important;font-weight:800 !important;margin:.2rem 0 .8rem !important;padding:0 0 .5rem !important;border-bottom:1px solid rgba(0,230,118,.35);background:linear-gradient(90deg,#b9ffd9,#00e676);-webkit-background-clip:text;background-clip:text;color:transparent !important}
.st-key-report h2{font-size:.95rem !important;font-weight:700 !important;letter-spacing:.06em;text-transform:uppercase;color:#00e676 !important;margin:1.4rem 0 .5rem !important;padding:.3rem 0 .3rem .7rem !important;border-left:3px solid #00e676;background:linear-gradient(90deg,rgba(0,230,118,.12),transparent)}
.st-key-report h3{font-size:.9rem !important;font-weight:700 !important;color:#9ff0c0 !important;margin:1rem 0 .3rem !important;padding:0 !important}
.st-key-report h4{font-size:.85rem !important;color:#bfe9d1 !important;margin:.8rem 0 .2rem !important;padding:0 !important}
.st-key-report strong{color:#eafff3}
.st-key-report a{color:#69f0ae !important;text-decoration:none !important;border-bottom:1px dotted #69f0ae}
.st-key-report a:hover{text-shadow:0 0 8px #00e676}
.st-key-report ul,.st-key-report ol{padding-left:1.2rem}
.st-key-report li::marker{color:#00e676}
.st-key-report table{display:block;overflow-x:auto;width:100%;border-collapse:separate;border-spacing:0;border:1px solid rgba(0,230,118,.3);border-radius:10px;font-size:.8rem;margin:.6rem 0 1rem}
.st-key-report th{background:rgba(0,230,118,.14) !important;color:#b9ffd9 !important;font-weight:700 !important;text-align:left;padding:.45rem .7rem !important;white-space:nowrap}
.st-key-report td{padding:.4rem .7rem !important;border-top:1px solid rgba(0,230,118,.12) !important;vertical-align:top}
.st-key-report th,.st-key-report td{border-left:none !important;border-right:none !important}
.st-key-report tr:nth-child(even) td{background:rgba(0,230,118,.04)}
.st-key-report blockquote{border-left:3px solid #00e676 !important;background:rgba(0,230,118,.07);padding:.5rem .9rem !important;border-radius:0 8px 8px 0;margin:.6rem 0}
.st-key-report hr{border-color:rgba(0,230,118,.2) !important;margin:1rem 0}
.st-key-report code{font-size:.8rem;background:rgba(0,230,118,.1);color:#b9ffd9;border-radius:5px;padding:.05rem .35rem}
"""